-- Feature 017 canonical generation lineage. This is the target baseline used after migration
-- archaeology is removed; every operational record is append-only by policy and trigger.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE "ProjectStatus" AS ENUM ('ACTIVE', 'ARCHIVED');
CREATE TYPE "StoryboardStatus" AS ENUM ('ACTIVE', 'ARCHIVED');
CREATE TYPE "AssetStatus" AS ENUM ('PRESERVED', 'READY', 'INVALID', 'REMOVED');
CREATE TYPE "GenerationAttemptState" AS ENUM ('QUEUED', 'LEASED', 'SUBMITTING', 'SUBMITTED', 'RECONCILING', 'COMPLETED', 'FAILED', 'AMBIGUOUS', 'CANCELLED');
CREATE TYPE "AuthorizationState" AS ENUM ('ACTIVE', 'CONSUMED', 'EXPIRED', 'CANCELLED');
CREATE TYPE "OwnerDecisionType" AS ENUM ('PASS', 'FAIL', 'RISK_ACCEPTED');

CREATE TABLE "Project" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "name" VARCHAR(240) NOT NULL, "status" "ProjectStatus" NOT NULL DEFAULT 'ACTIVE', "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE "Asset" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "projectId" UUID NOT NULL REFERENCES "Project"("id") ON DELETE RESTRICT, "storageKey" VARCHAR(500) NOT NULL UNIQUE, "sha256" CHAR(64) NOT NULL, "mediaType" VARCHAR(40) NOT NULL, "status" "AssetStatus" NOT NULL DEFAULT 'PRESERVED', "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX "Asset_projectId_createdAt_idx" ON "Asset"("projectId", "createdAt");
CREATE TABLE "Storyboard" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "projectId" UUID NOT NULL REFERENCES "Project"("id") ON DELETE RESTRICT, "title" VARCHAR(240) NOT NULL, "status" "StoryboardStatus" NOT NULL DEFAULT 'ACTIVE', "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX "Storyboard_projectId_createdAt_idx" ON "Storyboard"("projectId", "createdAt");
CREATE TABLE "StoryboardVersion" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "storyboardId" UUID NOT NULL REFERENCES "Storyboard"("id") ON DELETE RESTRICT, "ordinal" INTEGER NOT NULL, "payloadJson" JSONB NOT NULL, "digest" CHAR(64) NOT NULL, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE ("storyboardId", "ordinal"), UNIQUE ("storyboardId", "digest"));
CREATE TABLE "StoryboardShot" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "storyboardVersionId" UUID NOT NULL REFERENCES "StoryboardVersion"("id") ON DELETE RESTRICT, "ordinal" INTEGER NOT NULL, "payloadJson" JSONB NOT NULL, "digest" CHAR(64) NOT NULL, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE ("storyboardVersionId", "ordinal"), UNIQUE ("storyboardVersionId", "digest"));
CREATE TABLE "CapabilityProfile" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "ref" VARCHAR(160) NOT NULL, "version" VARCHAR(80) NOT NULL, "schemaVersion" INTEGER NOT NULL DEFAULT 1, "payloadJson" JSONB NOT NULL, "digest" CHAR(64) NOT NULL, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE ("ref", "version"));
CREATE TABLE "RuntimeContract" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "capabilityProfileId" UUID NOT NULL REFERENCES "CapabilityProfile"("id") ON DELETE RESTRICT, "ref" VARCHAR(160) NOT NULL, "version" VARCHAR(80) NOT NULL, "nodeClassesJson" JSONB NOT NULL, "digest" CHAR(64) NOT NULL, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE ("ref", "version"));
CREATE TABLE "GenerationImplementation" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "capabilityProfileId" UUID NOT NULL REFERENCES "CapabilityProfile"("id") ON DELETE RESTRICT, "runtimeContractId" UUID NOT NULL REFERENCES "RuntimeContract"("id") ON DELETE RESTRICT, "ref" VARCHAR(160) NOT NULL, "version" VARCHAR(80) NOT NULL, "providerRef" JSONB NOT NULL, "modelRef" JSONB NOT NULL, "adapterRef" JSONB NOT NULL, "compilerRef" JSONB NOT NULL, "validatorRef" JSONB NOT NULL, "lifecycle" VARCHAR(20) NOT NULL, "digest" CHAR(64) NOT NULL, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE ("ref", "version"));
CREATE TABLE "CapabilityPublicationReceipt" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "actorRef" VARCHAR(160) NOT NULL, "manifestJson" JSONB NOT NULL, "manifestSha256" CHAR(64) NOT NULL UNIQUE, "capabilityProfileId" UUID NOT NULL REFERENCES "CapabilityProfile"("id") ON DELETE RESTRICT, "implementationId" UUID NOT NULL REFERENCES "GenerationImplementation"("id") ON DELETE RESTRICT, "receiptDigest" CHAR(64) NOT NULL UNIQUE, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX "CapabilityPublicationReceipt_capabilityProfileId_createdAt_idx" ON "CapabilityPublicationReceipt" ("capabilityProfileId", "createdAt");
CREATE INDEX "CapabilityPublicationReceipt_implementationId_createdAt_idx" ON "CapabilityPublicationReceipt" ("implementationId", "createdAt");
CREATE TABLE "ShotGenerationRequirement" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "projectId" UUID NOT NULL REFERENCES "Project"("id") ON DELETE RESTRICT, "storyboardVersionId" UUID NOT NULL REFERENCES "StoryboardVersion"("id") ON DELETE RESTRICT, "shotId" UUID NOT NULL REFERENCES "StoryboardShot"("id") ON DELETE RESTRICT, "payloadJson" JSONB NOT NULL, "digest" CHAR(64) NOT NULL, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE ("shotId", "digest"));
CREATE TABLE "PlanningInputSnapshot" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "requirementId" UUID NOT NULL REFERENCES "ShotGenerationRequirement"("id") ON DELETE RESTRICT, "payloadJson" JSONB NOT NULL, "digest" CHAR(64) NOT NULL, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE ("requirementId", "digest"));
CREATE TABLE "GenerationSpec" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "planningInputSnapshotId" UUID NOT NULL REFERENCES "PlanningInputSnapshot"("id") ON DELETE RESTRICT, "implementationId" UUID NOT NULL REFERENCES "GenerationImplementation"("id") ON DELETE RESTRICT, "runtimeContractId" UUID NOT NULL REFERENCES "RuntimeContract"("id") ON DELETE RESTRICT, "payloadJson" JSONB NOT NULL, "digest" CHAR(64) NOT NULL, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE ("planningInputSnapshotId", "digest"));
CREATE TABLE "ReferencePlan" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "generationSpecId" UUID NOT NULL UNIQUE REFERENCES "GenerationSpec"("id") ON DELETE RESTRICT, "payloadJson" JSONB NOT NULL, "digest" CHAR(64) NOT NULL UNIQUE, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE "MaterializedGraphSnapshot" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "generationSpecId" UUID NOT NULL UNIQUE REFERENCES "GenerationSpec"("id") ON DELETE RESTRICT, "referencePlanId" UUID NOT NULL REFERENCES "ReferencePlan"("id") ON DELETE RESTRICT, "graphJson" JSONB NOT NULL, "graphSha256" CHAR(64) NOT NULL UNIQUE, "runtimeContractDigest" CHAR(64) NOT NULL, "outputNodeId" VARCHAR(160) NOT NULL, "outputMediaKey" VARCHAR(160) NOT NULL, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE "GenerationPlan" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "projectId" UUID NOT NULL REFERENCES "Project"("id") ON DELETE RESTRICT, "payloadJson" JSONB NOT NULL, "digest" CHAR(64) NOT NULL, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE ("projectId", "digest"));
CREATE TABLE "GenerationAuthorization" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "generationPlanId" UUID NOT NULL REFERENCES "GenerationPlan"("id") ON DELETE RESTRICT, "scopeJson" JSONB NOT NULL, "generationLimit" INTEGER NOT NULL CHECK ("generationLimit" > 0), "aiQaLimit" INTEGER NOT NULL CHECK ("aiQaLimit" >= 0), "generationPriceMicros" BIGINT, "aiQaPriceMicros" BIGINT, "expiresAt" TIMESTAMPTZ NOT NULL, "state" "AuthorizationState" NOT NULL DEFAULT 'ACTIVE', "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE "GenerationBatch" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "generationPlanId" UUID NOT NULL REFERENCES "GenerationPlan"("id") ON DELETE RESTRICT, "authorizationId" UUID NOT NULL UNIQUE REFERENCES "GenerationAuthorization"("id") ON DELETE RESTRICT, "idempotencyKey" VARCHAR(160) NOT NULL UNIQUE, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE "GenerationTarget" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "generationBatchId" UUID NOT NULL REFERENCES "GenerationBatch"("id") ON DELETE RESTRICT, "generationSpecId" UUID NOT NULL REFERENCES "GenerationSpec"("id") ON DELETE RESTRICT, "ordinal" INTEGER NOT NULL, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE ("generationBatchId", "ordinal"));
CREATE TABLE "GenerationAttempt" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "generationTargetId" UUID NOT NULL REFERENCES "GenerationTarget"("id") ON DELETE RESTRICT, "adapterRef" JSONB NOT NULL, "runtimeRef" JSONB NOT NULL, "runtimeContractDigest" CHAR(64) NOT NULL, "graphSha256" CHAR(64) NOT NULL, "state" "GenerationAttemptState" NOT NULL DEFAULT 'QUEUED', "providerTaskId" VARCHAR(500) UNIQUE, "terminalCode" VARCHAR(160), "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE ("generationTargetId"));
CREATE TABLE "GenerationAttemptEvent" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "attemptId" UUID NOT NULL REFERENCES "GenerationAttempt"("id") ON DELETE RESTRICT, "state" "GenerationAttemptState" NOT NULL, "taskId" VARCHAR(500), "code" VARCHAR(160), "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE ("attemptId", "state", "createdAt"));
CREATE TABLE "AuthorizationConsumption" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "authorizationId" UUID NOT NULL REFERENCES "GenerationAuthorization"("id") ON DELETE RESTRICT, "attemptId" UUID NOT NULL REFERENCES "GenerationAttempt"("id") ON DELETE RESTRICT, "operation" VARCHAR(20) NOT NULL, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE ("attemptId", "operation"));
CREATE TABLE "GenerationArtifact" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "attemptId" UUID NOT NULL UNIQUE REFERENCES "GenerationAttempt"("id") ON DELETE RESTRICT, "storageKey" VARCHAR(500) NOT NULL UNIQUE, "sha256" CHAR(64) NOT NULL, "ffprobeJson" JSONB NOT NULL, "framesJson" JSONB NOT NULL, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE "AiQaRun" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "artifactId" UUID NOT NULL REFERENCES "GenerationArtifact"("id") ON DELETE RESTRICT, "authorizationConsumptionId" UUID NOT NULL UNIQUE REFERENCES "AuthorizationConsumption"("id") ON DELETE RESTRICT, "state" VARCHAR(20) NOT NULL, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE "AiQaResult" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "aiQaRunId" UUID NOT NULL UNIQUE REFERENCES "AiQaRun"("id") ON DELETE RESTRICT, "payloadJson" JSONB NOT NULL, "digest" CHAR(64) NOT NULL, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE "OwnerDecision" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "artifactId" UUID NOT NULL REFERENCES "GenerationArtifact"("id") ON DELETE RESTRICT, "decision" "OwnerDecisionType" NOT NULL, "actorRef" VARCHAR(160) NOT NULL, "idempotencyKey" VARCHAR(160) NOT NULL UNIQUE, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE "RetryPreview" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "ownerDecisionId" UUID NOT NULL UNIQUE REFERENCES "OwnerDecision"("id") ON DELETE RESTRICT, "payloadJson" JSONB NOT NULL, "digest" CHAR(64) NOT NULL UNIQUE, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE "GenerationAssembly" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "projectId" UUID NOT NULL REFERENCES "Project"("id") ON DELETE RESTRICT, "inputDigest" CHAR(64) NOT NULL UNIQUE, "idempotencyKey" VARCHAR(160) NOT NULL UNIQUE, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now());

CREATE FUNCTION "mainline_append_only"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Feature 017 lineage is append-only'; END; $$;
CREATE TRIGGER "CapabilityProfile_no_mutation" BEFORE UPDATE OR DELETE ON "CapabilityProfile" FOR EACH ROW EXECUTE FUNCTION "mainline_append_only"();
CREATE TRIGGER "RuntimeContract_no_mutation" BEFORE UPDATE OR DELETE ON "RuntimeContract" FOR EACH ROW EXECUTE FUNCTION "mainline_append_only"();
CREATE TRIGGER "GenerationImplementation_no_mutation" BEFORE UPDATE OR DELETE ON "GenerationImplementation" FOR EACH ROW EXECUTE FUNCTION "mainline_append_only"();
CREATE TRIGGER "CapabilityPublicationReceipt_no_mutation" BEFORE UPDATE OR DELETE ON "CapabilityPublicationReceipt" FOR EACH ROW EXECUTE FUNCTION "mainline_append_only"();
CREATE TRIGGER "ShotGenerationRequirement_no_mutation" BEFORE UPDATE OR DELETE ON "ShotGenerationRequirement" FOR EACH ROW EXECUTE FUNCTION "mainline_append_only"();
CREATE TRIGGER "PlanningInputSnapshot_no_mutation" BEFORE UPDATE OR DELETE ON "PlanningInputSnapshot" FOR EACH ROW EXECUTE FUNCTION "mainline_append_only"();
CREATE TRIGGER "GenerationSpec_no_mutation" BEFORE UPDATE OR DELETE ON "GenerationSpec" FOR EACH ROW EXECUTE FUNCTION "mainline_append_only"();
CREATE TRIGGER "ReferencePlan_no_mutation" BEFORE UPDATE OR DELETE ON "ReferencePlan" FOR EACH ROW EXECUTE FUNCTION "mainline_append_only"();
CREATE TRIGGER "MaterializedGraphSnapshot_no_mutation" BEFORE UPDATE OR DELETE ON "MaterializedGraphSnapshot" FOR EACH ROW EXECUTE FUNCTION "mainline_append_only"();
CREATE TRIGGER "GenerationPlan_no_mutation" BEFORE UPDATE OR DELETE ON "GenerationPlan" FOR EACH ROW EXECUTE FUNCTION "mainline_append_only"();
CREATE TRIGGER "GenerationAuthorization_no_mutation" BEFORE UPDATE OR DELETE ON "GenerationAuthorization" FOR EACH ROW EXECUTE FUNCTION "mainline_append_only"();
CREATE TRIGGER "GenerationBatch_no_mutation" BEFORE UPDATE OR DELETE ON "GenerationBatch" FOR EACH ROW EXECUTE FUNCTION "mainline_append_only"();
CREATE TRIGGER "GenerationTarget_no_mutation" BEFORE UPDATE OR DELETE ON "GenerationTarget" FOR EACH ROW EXECUTE FUNCTION "mainline_append_only"();
CREATE TRIGGER "AuthorizationConsumption_no_mutation" BEFORE UPDATE OR DELETE ON "AuthorizationConsumption" FOR EACH ROW EXECUTE FUNCTION "mainline_append_only"();
CREATE TRIGGER "GenerationAttempt_no_mutation" BEFORE UPDATE OR DELETE ON "GenerationAttempt" FOR EACH ROW EXECUTE FUNCTION "mainline_append_only"();
CREATE TRIGGER "GenerationAttemptEvent_no_mutation" BEFORE UPDATE OR DELETE ON "GenerationAttemptEvent" FOR EACH ROW EXECUTE FUNCTION "mainline_append_only"();
CREATE TRIGGER "GenerationArtifact_no_mutation" BEFORE UPDATE OR DELETE ON "GenerationArtifact" FOR EACH ROW EXECUTE FUNCTION "mainline_append_only"();
CREATE TRIGGER "AiQaRun_no_mutation" BEFORE UPDATE OR DELETE ON "AiQaRun" FOR EACH ROW EXECUTE FUNCTION "mainline_append_only"();
CREATE TRIGGER "AiQaResult_no_mutation" BEFORE UPDATE OR DELETE ON "AiQaResult" FOR EACH ROW EXECUTE FUNCTION "mainline_append_only"();
CREATE TRIGGER "OwnerDecision_no_mutation" BEFORE UPDATE OR DELETE ON "OwnerDecision" FOR EACH ROW EXECUTE FUNCTION "mainline_append_only"();
CREATE TRIGGER "RetryPreview_no_mutation" BEFORE UPDATE OR DELETE ON "RetryPreview" FOR EACH ROW EXECUTE FUNCTION "mainline_append_only"();
